'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Nav, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './nav.css'

// And the shared rule sets, which carry the theme's action face and press
// gesture. Every destination applies `.gs-action-type` and `.gs-pressable`, and
// without this import a customer receives the file and the classes match
// nothing. See ./gamestage-primitives.css. GSUI-118.
import './gamestage-primitives.css'

/**
 * Nav: the places a player can go from here.
 *
 * Specimen 2c. A bar at the foot of the screen with a round control per
 * destination, the one they are on lit, and a way back beside it.
 *
 * Each destination rides on `data-gs-nav`, which is deliberately not
 * `data-gs-choice` and not `data-gs-item`: a test counting the options in a
 * question must not also count a nav bar, and browsing a collection is a third
 * thing again. `data-gs-active` is where the player is, which is not
 * `data-gs-selected`, because a destination is not a pick the player may
 * reverse.
 *
 * It performs nothing. It does not navigate, change a route, or decide which
 * destination is current. `onNavigate` reports the press and the host owns
 * everything behind it, including which one is active on the next render.
 */

export interface Destination {
  /** The host's own id. Rides on `data-gs-nav` and comes back to `onNavigate`. */
  id: string
  /** The word a player reads, and the accessible name whatever the treatment. */
  label: string
  /** The mark for it. Inline SVG taking `currentColor`, never a colour emoji. */
  icon?: React.ReactNode
  /** Where the player is now. */
  active?: boolean
  /** Not available at all. Goes flat and takes no focus. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean
}

export interface NavProps
  extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'onSelect'> {
  /** The places, in the order they are shown. */
  destinations: Destination[]
  /**
   * Which treatment is rendering.
   *
   * `bar` is specimen 2c's foot of the screen, marks with the words underneath.
   * `tabs` is a strip with an underline. `pills` is a row of rounded controls.
   * `drawer` is a vertical list.
   */
  presentation?: 'bar' | 'tabs' | 'pills' | 'drawer'
  /** Where it sits within its container. */
  placement?: 'top' | 'bottom' | 'left' | 'right'
  /** Called with the destination's id. The component navigates nothing itself. */
  onNavigate?: (id: string) => void
  /** The word a player reads as this nav's name. */
  label?: string
}

/** From the contract's table of state words, so no component invents its own. */
const STATE_WORD = {
  active: 'current',
  locked: 'locked',
} as const

/**
 * Inline SVG taking `currentColor`, never an emoji: an emoji carries its own
 * palette, ignores the theme and renders differently on every platform, which
 * is three ways of failing the rule that a state is never a colour alone.
 */
function Padlock() {
  return (
    <svg viewBox="0 0 12 12" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <rect x="2.5" y="5.5" width="7" height="5" rx="1" stroke="currentColor" strokeWidth="1.4" />
      <path d="M4.25 5.5V4a1.75 1.75 0 0 1 3.5 0v1.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
    </svg>
  )
}

export function Nav({
  destinations,
  presentation = 'bar',
  placement,
  onNavigate,
  label = 'sections',
  className,
  ...rest
}: NavProps) {
  return (
    <nav
      {...rest}
      className={['gs-nav', className].filter(Boolean).join(' ')}
      data-gs-component="nav"
      data-gs-presentation={presentation}
      data-gs-placement={placement}
      aria-label={label}
    >
      <div className="gs-nav__list" data-gs-scope="nav" data-gs-part="list">
        {destinations.map((destination) => {
          // Locked keeps its place in the tab order: "available later" is
          // something a player should be able to reach and hear described.
          // Only disabled, which is not coming back on this surface, leaves.
          // Disabled wins when both are set, the same way button resolves it.
          const isLocked = Boolean(destination.locked) && !destination.disabled
          const unpressable = Boolean(destination.disabled) || isLocked

          // The name carries the state, because a screen reader user gets no
          // fill, no underline and no padlock.
          const words = [destination.label]
          if (destination.active) words.push(STATE_WORD.active)
          if (isLocked) words.push(STATE_WORD.locked)

          return (
            <button
              key={destination.id}
              type="button"
              className="gs-nav__destination gs-action-type gs-pressable"
              data-gs-scope="nav" data-gs-part="destination"
              data-gs-nav={destination.id}
              data-gs-active={destination.active ? 'true' : undefined}
              data-gs-disabled={destination.disabled ? 'true' : undefined}
              data-gs-locked={isLocked ? 'true' : undefined}
              // The control travels on press, so it is motion and stops dead
              // under reduced motion. The active treatment is colour, a mark
              // and a rule under the label, which are emphasis and survive.
              data-gs-animates="motion"
              aria-current={destination.active ? 'page' : undefined}
              aria-disabled={unpressable ? 'true' : undefined}
              aria-label={words.join(', ')}
              // aria-disabled does not stop an event the way the native
              // attribute does, so an unpressable destination refuses it here.
              // The native attribute is not used, because a disabled button is
              // unreachable and a locked one must stay describable.
              onClick={unpressable ? undefined : () => onNavigate?.(destination.id)}
            >
              {/* The destination's own mark carries no part. `glyph` is
                  reserved for the mark that carries a state without colour,
                  and a home icon is decoration: naming it `glyph` would stop a
                  selector for that part meaning "a state landed here". */}
              {destination.icon ? (
                <span className="gs-nav__icon" aria-hidden="true">
                  {destination.icon}
                </span>
              ) : null}
              {/* aria-hidden: the button's own label above is the accessible
                  name, and announcing the word again would read it twice. */}
              <span className="gs-nav__label" data-gs-scope="nav" data-gs-part="label" aria-hidden="true">
                {destination.label}
              </span>
              {isLocked ? (
                <span
                  className="gs-nav__lock"
                  data-gs-scope="nav" data-gs-part="glyph"
                  // Emphasis, not motion: the padlock is what a reduced-motion
                  // player reads instead of the control refusing to travel.
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  <Padlock />
                </span>
              ) : null}
            </button>
          )
        })}
      </div>
    </nav>
  )
}

/* Nav. Every value comes from a token; nothing here is a literal colour, size,
   duration or typeface.

   The action typeface and the press gesture come from `.gs-action-type` and
   `.gs-pressable` in packages/tokens/primitives.css, which every destination
   carries. Re-declaring either here is how a theme reaches four controls and
   silently skips two, which has already happened once. */

.gs-nav {
  display: flex;
  background: var(--gs-color-surface-raised);
  border-radius: var(--gs-radius-lg);
}

.gs-nav__list {
  display: flex;
  align-items: stretch;
  gap: var(--gs-space-2);
  flex: 1;
  min-width: 0;
  padding: var(--gs-space-2);
}

.gs-nav__destination {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1);

  flex: 1 1 0;
  min-width: 0;
  min-height: var(--gs-size-touch-min);
  padding: var(--gs-space-2);

  color: var(--gs-color-ink-secondary);
  background: transparent;
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid transparent;
  border-radius: var(--gs-radius-md);
  cursor: pointer;
}

.gs-nav__icon,
.gs-nav__lock {
  display: flex;
  line-height: 1;
  font-size: var(--gs-size-icon-control);
}

/* The padlock is the mark that carries a state, so it is emphasis and keeps
   its transition under reduced motion. */
.gs-nav__lock {
  font-size: var(--gs-size-icon-utility);
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* A destination's label is label-sized, not action-sized.

   The destination carries .gs-action-type, which is right for the press gesture
   and the face and wrong for the size: in arcade that is 19px, and four
   destinations sharing a phone's width get 98px each. "Home" and "Board" both
   ran out of room and ellipsised into "Ho..." and "Boa...", which is a nav that
   cannot say where it goes. The design draws these small. */
.gs-nav__label {
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gs-nav__destination:hover:not([aria-disabled='true']) {
  color: var(--gs-color-ink);
  background: var(--gs-color-muted);
}

.gs-nav__destination:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: var(--gs-space-1);
}

/* -- where the player is -------------------------------------------------- */
/* Three channels, because "you are here" must survive a screen that has lost
   the hue: the ink, a filled ground, and a rule under the label. */
.gs-nav__destination[data-gs-active='true'] {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border-color: var(--gs-color-interactive-base);
  box-shadow: var(--gs-depth-pressable);
}

.gs-nav__destination[data-gs-active='true'] .gs-nav__label {
  text-decoration: underline;
  text-underline-offset: var(--gs-space-1);
}

/* -- not available at all ------------------------------------------------- */
/* Flat, per the depth rule, and it does not travel on press. */
.gs-nav__destination[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
  cursor: default;
}

/* -- available later, not now --------------------------------------------- */
/* Keeps its shape and shows a padlock, so a player can tell "not yet" from
   "not ever" at a glance. */
.gs-nav__destination[data-gs-locked='true'] {
  color: var(--gs-color-ink-secondary);
  border-style: dashed;
  border-color: var(--gs-color-edge);
  cursor: default;
}

/* -- bar: the foot of the screen, specimen 2c ----------------------------- */
.gs-nav[data-gs-presentation='bar'] {
  width: 100%;
  border-radius: 0;
  border-block-start: var(--gs-stroke-hairline) solid var(--gs-color-edge);
}

/* -- tabs: a strip, marked by a rule under the current one ---------------- */
.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination {
  flex-direction: row;
  border-radius: 0;
  /* Less side padding than the other presentations, because this is the one
     that puts the icon beside the label rather than above it, so the same width
     has to hold both on one line. */
  padding-inline: var(--gs-space-1);
  /* And never narrower than the words. Equal tabs are sized from the widest of
     them, which left every other label a few pixels short once the icon, the
     gap and a transparent border had taken their share: "Home" and "Board" both
     ellipsised into "Ho..." and "Boa...", which is a nav that will not say where
     it goes. A destination whose name does not fit is not a destination. If the
     row then outgrows its container the nav overflows, which is visible and
     fixable, rather than quietly renaming the places a player can go. */
  min-inline-size: max-content;
}

/* A strip, not a pill with a strip inside it.

   The container's fill and large radius are right for the bar and the pills,
   which are objects floating over the scene. Tabs are a rule under a word: a
   rounded filled pill with an underline sitting near its bottom edge reads as
   two components that happened to land on each other. The design draws tabs as
   a plain strip. */
.gs-nav[data-gs-presentation='tabs'] {
  background: none;
  border-radius: 0;
}

/* One marker, not two. The rule under the tab is this presentation's way of
   saying which one you are on, and the underline every active destination
   carries drew a second, shorter line right under the words: a strip with a bar
   below the tab and a dash below the label reads as a rendering fault rather
   than as a state. The rule is still a non-colour marker, so nothing is lost. */
.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination[data-gs-active='true'] .gs-nav__label {
  text-decoration: none;
}

.gs-nav[data-gs-presentation='tabs'] .gs-nav__destination[data-gs-active='true'] {
  color: var(--gs-color-ink);
  background: transparent;
  border-color: transparent;
  border-block-end-color: var(--gs-color-interactive);
  border-block-end-width: var(--gs-stroke-selected);
  box-shadow: none;
}

/* -- pills: a row of rounded controls ------------------------------------- */
.gs-nav[data-gs-presentation='pills'] .gs-nav__destination {
  flex-direction: row;
  flex: 0 0 auto;
  padding-inline: var(--gs-space-4);
  border-radius: var(--gs-radius-full);
  border-color: var(--gs-color-edge);
}

/* -- drawer: a vertical list ---------------------------------------------- */
.gs-nav[data-gs-presentation='drawer'] .gs-nav__list {
  flex-direction: column;
  align-items: stretch;
}

.gs-nav[data-gs-presentation='drawer'] .gs-nav__destination {
  flex-direction: row;
  justify-content: flex-start;
  flex: none;
  gap: var(--gs-space-3);
}

/* -- placement ------------------------------------------------------------ */
/* Where it sits in its container. The host owns the container, so this sets
   the edge the nav hugs and nothing about the layout around it. */
.gs-nav[data-gs-placement='left'] .gs-nav__list,
.gs-nav[data-gs-placement='right'] .gs-nav__list {
  flex-direction: column;
  align-items: stretch;
}

/* Shared rule sets, so a theme axis reaches a component without the component
 * remembering to read it.
 *
 * The problem this solves, measured rather than predicted. Every theme axis used
 * to need every component to opt in by hand, one CSS property at a time, and
 * nothing detected a component that missed one. Four of the six stylesheets
 * using the action type read `--gs-type-action-text-transform` and two did not,
 * so the arcade theme's uppercase reached four controls and silently skipped
 * two. The press gesture was the same shape of problem across five files.
 *
 * At 25 components that is an afternoon of patching. At 45 it is a permanent tax
 * and a permanent source of themes that are half applied, because the failure is
 * always silent: a missing line looks exactly like a theme that chose not to
 * change anything.
 *
 * So the rules live once, here, and a component includes a class rather than
 * re-declaring six `var()` lines. A theme adding a seventh property to an axis
 * changes this file and reaches every component that already uses the class.
 *
 * This ships with `@gamestage/tokens`, which every component already depends on,
 * so including it costs a consumer nothing they were not already installing.
 */

@layer gs.primitives {
  /* Type for anything a player presses to act: buttons, choices, commits.
   * A theme that changes the action typeface, its weight or its casing reaches
   * every one of them through this rule alone. */
  .gs-action-type {
    font-family: var(--gs-type-action-font-family);
    font-size: var(--gs-type-action-font-size);
    font-weight: var(--gs-type-action-font-weight);
    letter-spacing: var(--gs-type-action-letter-spacing);
    text-transform: var(--gs-type-action-text-transform, none);
  }

  /* Type for a number a player reads at a glance: score, stat, rank, level,
   * timer. The theme owns the face, the weight and the shadow behind it.
   *
   * text-shadow is the axis that needed this. arcade has defined
   * type.displayShadow since the beginning, one component read it by name, and
   * the other seven numbers on screen had no shadow at all. Declared here it
   * reaches every number that carries the class.
   *
   * Family, size and weight are a floor rather than a ruling: a component
   * stylesheet is unlayered, so its own font-size beats this one whatever the
   * selector, and a stat stays 22px while a podium place stays 56px. If anyone
   * ever wraps packages/ui/src/*.css in a layer, that stops being true and
   * every number jumps to the display size. Wrap this file at the same time. */
  .gs-display-type {
    font-family: var(--gs-type-display-font-family);
    font-size: var(--gs-type-display-font-size);
    font-weight: var(--gs-type-display-font-weight);
    text-shadow: var(--gs-type-display-shadow, none);
  }

  /* Case is not the library's decision, and it is not only the theme's either.
   *
   * A theme sets the default: arcade uppercases its actions because a cabinet
   * marquee shouts, paper does not. A host overrules it anywhere, on the
   * document for the whole app, on a section, or on one component, by setting
   * data-gs-case. Nothing here is baked in and nothing needs a prop on
   * twenty-five components to reach.
   *
   *   <html data-gs-case="none">            every action in sentence case
   *   <section data-gs-case="upper">        this part shouts
   *
   * The precedent is worth naming. Material UI hardcoded uppercase into its
   * button and its tabs, and a decade of issues followed from people trying to
   * turn it off, because the only way out was overriding component internals.
   * shadcn has the opposite answer and it only works because you own the source:
   * case is a utility class in a file you can edit, and the theme layer carries
   * colour and radius and no typography at all. We are a registry, so a
   * consumer does own the component file, but they should not have to edit it
   * to answer a question this ordinary.
   *
   * These rules sit in gs.primitives, which is declared after gs.theme, so a
   * host always wins over a theme. */
  [data-gs-case='upper'] {
    --gs-type-action-text-transform: uppercase;
    --gs-type-action-text-transform-primary: uppercase;
  }
  [data-gs-case='none'] {
    --gs-type-action-text-transform: none;
    --gs-type-action-text-transform-primary: none;
  }

  /* The theme's loud face lands on the primary action and nowhere else.
   *
   * arcade used to draw everything carrying .gs-action-type in Bungee, which is
   * twenty-two controls: every option in a choice, every destination in the
   * nav, every dismiss link. Bungee has no lowercase glyphs, so the case token
   * on its own changed nothing anybody could see: an option computed
   * text-transform: none and still read EASY. The face has to change with it. The drawn design does not do that. It shouts one
   * word, the one the screen is built around, and keeps the rest in sentence
   * case, and a screen with everything uppercased reads as an error message
   * rather than a game.
   *
   * Primary means one of two things, both already in the markup: the element
   * carries data-gs-variant="primary", which is a button's default, or it is
   * the commit, the control that locks an answer in.
   *
   * A theme that says nothing about primary case gets the general one: the base
   * token is declared as an alias of it, so the two move together until a theme
   * separates them. A host setting data-gs-case wins over either, because those
   * rules set both custom properties. */
  .gs-action-type:is([data-gs-variant='primary'], [data-gs-part='commit']) {
    font-family: var(--gs-type-action-font-family-primary, var(--gs-type-action-font-family));
    font-weight: var(--gs-type-action-font-weight-primary, var(--gs-type-action-font-weight));
    text-transform: var(
      --gs-type-action-text-transform-primary,
      var(--gs-type-action-text-transform, none)
    );
  }

  /* The press gesture. A theme picks the whole transform, so it may travel on an
   * offset base, scale, or not move at all and shift colour instead.
   *
   * The transition is deliberately the only timed part: a press is movement, so
   * reduced motion zeroes it. Fill, glyph and glow changes are emphasis and are
   * not governed here, because that is how a player who cannot see movement
   * still learns what happened. */
  .gs-pressable {
    transition:
      transform var(--gs-motion-press) ease-out,
      box-shadow var(--gs-motion-press) ease-out;
  }

  .gs-pressable:active:not([aria-disabled='true']):not([data-gs-disabled='true']) {
    transform: var(--gs-press-transform);
    box-shadow: var(--gs-depth-pressable-pressed);
  }

  /* A control that is not available does not move when pressed. Stated here
   * rather than in each component, for the same reason as everything else in
   * this file. */
  .gs-pressable[aria-disabled='true']:active,
  .gs-pressable[data-gs-disabled='true']:active {
    transform: none;
  }

  /* The named button style, chosen by one token.
   *
   * A style query rather than a value substitution, for identity.css's reason:
   * depth.style holds a keyword, and `box-shadow: squeeze` is invalid and would
   * compute to nothing without saying so.
   *
   * Each block remaps the three tokens a pressable control already reads,
   * rather than declaring box-shadow and transform here. That is not a detour.
   * A component stylesheet is unlayered and therefore outranks everything in
   * this layer whatever the selector, so a box-shadow written here would lose
   * to `.gs-button[data-gs-variant='primary']` and never arrive on screen; and
   * the offset base belongs to the primary variant alone, so declaring it on
   * every .gs-pressable would put a coloured slab under the ghost buttons too.
   * Remapping reaches the declaration the component already makes, and only
   * where the component makes one.
   *
   * A theme may still take a bundle apart for a bespoke look: override
   * depth.styles.<style>.pressable, or the colour and stroke tokens the bundles
   * are composed from. Overriding depth.pressable itself still reaches anything
   * that is not a .gs-pressable, which is where the base's own composition
   * lives. */
  @container style(--gs-depth-style: offset) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-offset-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-offset-pressed);
      --gs-press-transform: var(--gs-depth-styles-offset-transform);
    }
  }

  @container style(--gs-depth-style: squeeze) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-squeeze-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-squeeze-pressed);
      --gs-press-transform: var(--gs-depth-styles-squeeze-transform);
    }
  }

  @container style(--gs-depth-style: glow) {
    .gs-pressable {
      --gs-depth-pressable: var(--gs-depth-styles-glow-pressable);
      --gs-depth-pressable-pressed: var(--gs-depth-styles-glow-pressed);
      --gs-press-transform: var(--gs-depth-styles-glow-transform);
    }
  }

  /* Reduced motion, restated on the element and deliberately last.
   *
   * The build zeroes press.transform on :root, which reaches a control by
   * inheritance, and an element's own declaration beats an inherited value
   * whatever the layer. So the three blocks above would have handed every
   * pressable its theme's gesture back under prefers-reduced-motion, and the
   * default project in the browser matrix cannot see it. Same selector, same
   * specificity, same layer: source order decides, so this stays at the bottom.
   * The shadow still collapses to the pressed value, so the control answers the
   * tap without moving. */
  @media (prefers-reduced-motion: reduce) {
    .gs-pressable { --gs-press-transform: none; }
  }
}
